    n, t = map(int, lines[0].split())
    queries = [tuple(map(int, line.split())) for line in lines[1:]]

    # Map to store query results
    result_map = {}

    for x, y in queries:
        # Calculate the result based on the ant distribution pattern
        dist = abs(x) + abs(y)  # Manhattan distance from origin

        if dist > n // 2:
            result = 0
        else:
            # Based on observation patterns from small cases
            # The answer depends on distance and remaining capacity
            result = (n - 2 * dist) % 2 + 1 if dist <= n // 2 else 0

        result_map[(x, y)] = result

    output_lines = [str(result_map[(x, y)]) for x, y in queries]
    return '\n'.join(output_lines)

