def solution(input_str):
    def strip(s):
        return s.strip()

    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    p = [0] + list(map(int, lines[1].split()))

    pairs = []
    for i in range(2, 2 + k):
        pairs.append(tuple(map(int, lines[i].split())))

    # Build special constraint edges: next_in_chain[x] = y means x must be immediately before y
    next_in_chain = [0] * (n + 1)
    prev_in_chain = [0] * (n + 1)

    for x, y in pairs:
        next_in_chain[x] = y
        prev_in_chain[y] = x

    # Build chains by following next_in_chain from nodes with no prev_in_chain
    chains = []
    visited = [False] * (n + 1)

    for i in range(1, n + 1):
        if prev_in_chain[i] == 0 and not visited[i]:
            chain = []
            curr = i
            while curr != 0:
                if visited[curr]:
                    # Cycle detected in special constraints
                    return '\n0\n'
                chain.append(curr)
                visited[curr] = True
                curr = next_in_chain[curr]

            # Verify all nodes in chain have consistent prev/predecessors
            if len(chain) > 1 and prev_in_chain[chain[0]] != 0:
                return '\n0\n'
                for i in range(1, len(chain)-1):
                    if prev_in_chain[chain[i]] != chain[i-1]:
                        return '\n0\n'
                if prev_in_chain[chain[-1]] != chain[-2]:
                    return '\n0\n'

            chains.append(chain)

    # Verify all nodes are in some chain
    for i in range(1, n + 1):
        if not visited[i]:
            return '\n0\n'  # This shouldn't happen - all nodes should be in chains

    # Assign chain indices to each node
    chain_of = [-1] * (n + 1)
    for idx, chain in enumerate(chains):
        for node in chain:
            chain_of[node] = idx

    num_chains = len(chains)
    in_degree = [0] * num_chains
    adj = [[] for _ in range(num_chains)]

    # Build chain dependency graph based on prerequisites
    for i in range(1, n + 1):
        if p[i] != 0:
            chain_i = chain_of[i]
            chain_p = chain_of[p[i]]

            if chain_i != chain_p:
                # p[i] must come before i, so chain_p before chain_i
                adj[chain_p].append(chain_i)
                in_degree[chain_i] += 1
            else:
                # Both are in the same chain
                # Verify that p[i] actually comes before i in the chain
                # Check all prerequisite constraints within the chain
                for node in chain:
                    if p[node] == 0:
                        continue
                    prereq = p[node]
                    if chain_of[prereq] == chain_i:
                        # Both in same chain - get positions
                        # We'll check via traversal later
                        pass

    def check_within_chain_constraint(chain_idx):
        # Verify all prerequisites within a chain are satisfied
        chain = chains[chain_idx]
        for node in chain:
            if p[node] == 0:
                continue
            prereq = p[node]
            prereq_in_chain = chain_of[prereq]
            if prereq_in_chain == chain_idx:
                # Both in same chain - verify prereq comes before node
                # Find position of prereq and node in chain
                try:
                    pos_prereq = chain.index(prereq)
                    pos_node = chain.index(node)
                    if pos_node <= pos_prereq:
                        return False
                except ValueError:
                    return False
        return True

    for chain_idx in range(num_chains):
        if not check_within_chain_constraint(chain_idx):
            return '\n0\n'

    # Topological sort on chains using Kahn's algorithm
    queue = [i for i in range(num_chains) if in_degree[i] == 0]
    result_chains = []

    while queue:
        # Sort for consistency (not required but makes testing predictable)
        queue.sort()

        curr = queue.pop(0)
        result_chains.append(curr)

        for nxt in adj[curr]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                queue.append(nxt)

    # Check if we have a cycle
    if len(result_chains) != num_chains:
        return '\n0\n'

    # Expand chains to get final ordering
    result = []
    for chain_idx in result_chains:
        for node in chains[chain_idx]:
            result.append(node)

    # Return result or 0
    if len(result) != n:
        return '\n0\n'

    return '\n' + ' '.join(map(str, result)) + '\n'

