def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse operations
    ops = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # Initialize answer array with -1 (unreachable)
    ans = [-1] * (m + 1)

    # reachable[j] = earliest time step to reach exactly j bananas
    # Initially, we have 0 bananas at time 0
    reachable = {0}

    for step in range(1, n + 1):
        t, x, y = ops[step - 1]
        new_reachable = set()
        new_reachable.add(0)  # We can always choose a_i = 0 and not change k

        target = step

        # For each count k that was reachable before this step
        for k in reachable:
            # We can apply the operation up to y times
            for a in range(y + 1):
                if a == 0:
                    new_k = k
                elif t == 1:
                    # Type 1: k := ⌈k + x⌉
                    new_k = k
                    for _ in range(a):
                        new_k = math.ceil(new_k + x)
                else:
                    # Type 2: k := ⌈k * x⌉
                    new_k = k
                    for _ in range(a):
                        new_k = math.ceil(new_k * x)

                # Only care about counts up to m
                if new_k <= m:
                    new_reachable.add(new_k)

        # Mark answers for new time steps
        for k in new_reachable:
            if ans[k] == -1:
                ans[k] = target

        reachable = new_reachable

    return ' '.join(map(str, ans[1:]))

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(2 * m)]

    for i in range(n):
        parts = list(map(int, lines[1 + i].split()))
        k = parts[0]
        clause = parts[1:k+1]

        # For each literal in the clause, if it's false, other literals must be true
        for j, lit in enumerate(clause):
            var = abs(lit) - 1
            is_neg = (lit < 0)

            for other in clause:
                if lit == other:
                    continue
                other_var = abs(other) - 1
                other_neg = (other < 0)

                # If current literal is false, the other must be true
                if is_neg:  # neg x_var is false means x_var is true
                    adj[2 * var].append(2 * other_var + (1 if other_neg else 2))
                else:  # pos x_var is false means neg x_var is true
                    adj[2 * var + 1].append(2 * other_var + (0 if other_neg else 1))

    # Compute topological order
    in_degree = [0] * (2 * m)
    for u in range(2 * m):
        for v in adj[u]:
            in_degree[v] += 1

    q = []
    for i in range(2 * m):
        if in_degree[i] == 0:
            q.append(i)

    topo_order = []
    index = 0
    while index < len(q):
        u = q[index]
        index += 1
        topo_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                q.append(v)

    # Check if all nodes are in topological order (no cycles)
    if len(topo_order) != 2 * m:
        return "NO"

    # Determine assignment: for each variable, put the one that appears later
    # in topo order if possible
    result = [0] * m
    for var in range(m):
        # Node 2*var represents NOT x_var, node 2*var+1 represents x_var
        # Later node in topo order can be set to true (1)
        node_true = 2 * var + 1
        node_false = 2 * var

        # Check topo order - if we can set this to true
        idx_true = -1
        idx_false = -1
        for idx, node in enumerate(topo_order):
            if node == node_true:
                idx_true = idx
            if node == node_false:
                idx_false = idx

        # Earlier node should be true if they're in a cycle/connected
        if idx_true != -1 and idx_false != -1:
            # if true node comes earlier, we can set true -> 1
            if idx_true < idx_false:
                result[var] = 1
            else:
                result[var] = 0
        elif idx_true != -1:
            result[var] = 1
        elif idx_false != -1:
            result[var] = 0
        else:
            result[var] = 0

    return "YES\n" + "".join(map(str, result))

import heapq

def solution(input_data):
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v, w = map(int, lines[i].split())
        adj[u].append((v, w, i))
        adj[v].append((u, w, i))

    start = int(lines[m + 1])

    # Dijkstra's algorithm to find shortest distances
    dist = [float('inf')] * (n + 1)
    dist[start] = 0
    pq = [(0, start)]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w, e_idx in adj[u]:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                heapq.heappush(pq, (dist[v], v))

    # Build shortest path tree - for each vertex, pick minimum weight edge on shortest path
    total_weight = 0
    selected_edges = []

    for v in range(1, n + 1):
        if v == start:
            continue

        best_e_idx = -1
        best_w = float('inf')

        for u, w, e_idx in adj[v]:
            # Check if this edge is on a shortest path to v
            if dist[u] + w == dist[v] and dist[u] < float('inf'):
                if w < best_w:
                    best_w = w
                    best_e_idx = e_idx

        if best_e_idx != -1:
            total_weight += best_w
            selected_edges.append(best_e_idx)

    return f"{total_weight}\n{' '.join(map(str, selected_edges))}"

