    def get_grundy(val):
        if k == 1:
            # For k=1, pattern is n % 2 for n >= 1
            return val % 2
        elif k == 2:
            # For k=2, pattern is n % 3
            return val % 3
        elif k == 3:
            # For k=3, after n>=4, pattern is period 2: even->1, odd->0
            if val <= 3:
                return [1, 2, 0, 1][val]
            if val % 2 == 0:
                return 1
            return 0

        # Precompute Grundy values for unknown k
        MAX_PRECOMP = 200
        g = [0] * MAX_PRECOMP

        for i in range(1, MAX_PRECOMP):
            reachable = {0}
            reachable.add(g[i-1])  # Option 1: remove a cow

            # Option 2: if i is even 2x, replace with k piles of size x
            if i % 2 == 0:
                x = i // 2
                # When replacing with k piles of size x:
                # Effect is g[x] XOR g[x] XOR ... XOR g[x] (k times)
                # = g[x] if k is odd, 0 if k is even
                if k % 2 == 1:
                    if x < MAX_PRECOMP:
                        reachable.add(g[x])
                else:
                    reachable.add(0)

            # Find mex (minimum excluded)
            mex = 0
            while mex in reachable:
                mex += 1
            g[i] = mex

        if val < MAX_PRECOMP:
            return g[val]

        # For larger values, the sequence becomes periodic
        start = 100
        period = 50
        return g[start + (val - start) % period]

    xor_sum = 0
    for pile in piles:
        xor_sum ^= get_grundy(pile)

    return "Kevin" if xor_sum != 0 else "Nicky"

