def solution(input_str: str) -> str:
    def get_divisors(n: int) -> List[int]:
        """Get all divisors of n greater than 1."""
        divs = []
        for i in range(2, int(math.sqrt(n)) + 1):
            if n % i == 0:
                divs.append(i)
                if i * i != n:
                    divs.append(n // i)
        divs.append(n)
        return sorted(divs)

    def gcd(a: int, b: int) -> int:
        """Compute GCD of two numbers."""
        while b:
            a, b = b, a % b
        return a

    def count_div_prime_factors(d: int) -> int:
        """Count distinct prime factors of d."""
        count = 0
        p = 2
        while p * p <= d:
            if d % p == 0:
                count += 1
                while d % p == 0:
                    d //= p
            p += 1 if p == 2 else 2
        if d > 1:
            count += 1
        return count

