        # If only 2 divisors, already optimal
        if len(divs) == 2:
            results.append(" ".join(map(str, divs)))
            results.append("0")
            continue

        # Option 1: Sort by prime factors (descending)
        divs_pf_sorted = sorted(divs, key=count_div_prime_factors, reverse=True)
        moves_pf = sum(1 for j in range(len(divs_pf_sorted)) 
                      if gcd(divs_pf_sorted[j], divs_pf_sorted[(j + 1) % len(divs_pf_sorted)]) == 1)

