def get_prime_factors(n):
    """Return dict mapping prime -> exponent for prime factorization of n"""
    factors = {}
    d = 2
    temp = n

    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1

    if temp > 1:
        factors[temp] = 1

    return factors

def max_flow(n_nodes, source, sink, edges):
    """Edmonds-Karp algorithm for max flow"""
    INF = float('inf')

    if not edges:
        return 0

    capacity = {}
    flow = {}

    for u, v, c in edges:
        capacity[(u, v)] = c
        capacity[(v, u)] = 0

    def bfs():
        parent = {}
        visited = {node: False for node in range(n_nodes)}
        queue = deque([source])
        visited[source] = True

        while queue:
            u = queue.popleft()
            if u == sink:
                break

            for v in range(n_nodes):
                if not visited[v]:
                    residual = capacity.get((u, v), 0) - flow.get((u, v), 0)
                    if residual > 0:
                        visited[v] = True
                        parent[v] = u
                        queue.append(v)

        if sink not in visited:
            return None, 0

        path_flow = INF
        curr = sink
        while curr != source:
            prev = parent[curr]
            residual = capacity.get((prev, curr), 0) - flow.get((prev, curr), 0)
            path_flow = min(path_flow, residual)
            curr = prev

        curr = sink
        while curr != source:
            prev = parent[curr]
            flow[(prev, curr)] = flow.get((prev, curr), 0) + path_flow
            flow[(curr, prev)] = flow.get((curr, prev), 0) - path_flow
            curr = prev

        return parent, path_flow

    total_flow = 0

    while True:
        parent, path_flow = bfs()
        if path_flow is None or path_flow == 0:
            break
        total_flow += path_flow

    return total_flow

