def solution(board_str):
    lines = board_str.strip().split('\n')
    grid = [line.split() for line in lines]

    n_rows = len(grid)

    @functools.lru_cache(maxsize=None)
    def grundy(state_tuple):
        reachable = set()

        # Horizontal moves - remove contiguous O's in same row
        for r in range(n_rows):
            row = grid[r]
            i = 0
            while i < len(row):
                if row[i] == 'O':
                    j = i + 1
                    while j < len(row) and row[j] == 'O':
                        j += 1
                    # Can remove any single cell in this segment
                    for k in range(i, j):
                        move_mask = 0
                        new_grid = [list(r) for r in state_tuple]
                        new_grid[r][k] = '.'
                        new_state = tuple(tuple(row_list) for row_list in new_grid)
                        reachable.add(grundy(new_state))
                i += 1

        # Diagonal direction 1: (r, c) -> (r+1, c) or (r+1, c+1)
        for r in range(n_rows - 1):
            for c in range(len(grid[r])):
                if grid[r][c] == 'O':
                    # Check diagonal pattern for hexagonal structure
                    for dc_next in [0, 1]:
                        nr = r + 1
                        nc = c + dc_next
                        if nr < n_rows and nc < len(grid[nr]):
                            if grid[nr][nc] == 'O':
                                # Mark contiguous diagonal segment
                                seg = [(r, c)]
                                cur_r, cur_c = r, c
                                while True:
                                    cur_r += 1
                                    for dc_next in [0, 1]:
                                        nc2 = cur_c + dc_next
                                        if cur_r < n_rows and nc2 < len(grid[cur_r]) and grid[cur_r][nc2] == 'O':
                                            seg.append((cur_r, nc2))
                                            cur_c = nc2
                                            break
                                    else:
                                        cur_c += 1
                                    if not (cur_r < n_rows and (cur_c or cur_c < len(grid[cur_r]))):
                                        break
                                    if len(seg) >= 2:
                                        break

                                for start in range(len(seg)):
                                    for end in range(start + 1, len(seg) + 1):
                                        new_grid = [list(row) for row in state_tuple]
                                        for ni, nj in seg[start:end]:
                                            new_grid[ni][nj] = '.'
                                        new_state = tuple(tuple(row) for row in new_grid)
                                        reachable.add(grundy(new_state))
                    continue
                i += 1

        # Direction 2: (r, c) -> (r+1, c-1) 
        for r in range(n_rows - 1):
            for c in range(len(grid[r])):
                if grid[r][c] == 'O':
                    for dc_next in [0, -1]:
                        nr = r + 1
                        nc = c + dc_next
                        if nr < n_rows and nc >= 0 and nc < len(grid[nr]):
                            if grid[nr][nc] == 'O':
                                # Similar contiguous scan
                                seg = [(r, c)]
                                for start in range(min(c + 1, len(grid[r]))):
                                    if start >= 0:
                                        pass

                                for start in range(len(seg)):
                                    for end in range(start + 1, len(seg) + 1):
                                        new_grid = [list(row) for row in state_tuple]
                                        for ni, nj in seg[start:end]:
                                            new_grid[ni][nj] = '.'
                                        new_state = tuple(tuple(row) for row in new_grid)
                                        reachable.add(grundy(new_state))

        mex = 0
        while mex in reachable:
            mex += 1
        return mex

    initial_state = tuple(tuple(row) for row in grid)
    g = grundy(initial_state)

    return 'Karlsson' if g > 0 else 'Lillebror'

