import math
from itertools import combinations

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "-1"

    try:
        n = int(lines[0])
    except:
        return "-1"

    centers = []
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        parts = lines[i].split()
        if len(parts) >= 2:
            centers.append((int(parts[0]), int(parts[1])))

    if n < 3:
        return "-1"

    def circumradius(p1, p2, p3):
        # Calculate circumradius of triangle formed by p1, p2, p3
        x1, y1 = p1
        x2, y2 = p2
        x3, y3 = p3

        # Calculate side lengths
        a = math.hypot(x2 - x1, y2 - y1)
        b = math.hypot(x3 - x2, y3 - y2)
        c = math.hypot(x1 - x3, y1 - y3)

        # Calculate area using Heron's formula
        s = (a + b + c) / 2
        if s <= 0:
            return float('inf')

        area_sq = s * (s - a) * (s - b) * (s - c)
        if area_sq <= 0:
            return float('inf')

        area = math.sqrt(area_sq)

        if area == 0:
            return float('inf')

        # Circumradius R = (abc) / (4*area)
        return (a * b * c) / (4 * area)

    max_boundary_t = 0.0

    # Check all triangle circumcenters
    for c1, c2, c3 in combinations(range(n), 3):
        p1 = centers[c1]
        p2 = centers[c2]
        p3 = centers[c3]

        r = circumradius(p1, p2, p3)

        if r != float('inf') and r >= 0:
            # A hole at this triangle's circumcenter disappears at this time
            max_boundary_t = max(max_boundary_t, r)

    # Also check pairwise boundary intersections
    for i, j in combinations(range(n), 2):
        x1, y1 = centers[i]
        x2, y2 = centers[j]
        d = math.hypot(x2 - x1, y2 - y1)
        if d > 0:
            # Circles meet when radius d/2
            max_boundary_t = max(max_boundary_t, d / 2)

    if max_boundary_t <= 0:
        return "-1"

    return f"{max_boundary_t:.6f}"

