    # If a=1, 1^b = 1 < n always, game goes forever (draw)
    if a == 1:
        return "Missing\n\n"

    @lru_cache(maxsize=None)
    def can_force_loss(a, b):
        """Returns True if current player can force opponent into losing position"""
        # Try adding a box
        if (a + 1) < n and ((a + 1) ** b < n):
            if not can_force_loss(a + 1, b):
                return True

        # Try adding an item  
        if a ** (b + 1) < n:
            if not can_force_loss(a, b + 1):
                return True

        return False

    # Check all possible next states are winning for opponent
    # (meaning current state is losing)
    has_winning_move = False

    # Check adding box
    if (a + 1) < n and ((a + 1) ** b < n):
        if not can_force_loss(a + 1, b):
            has_winning_move = True

    # Check adding item (only needed if no winning move via adding box)
    if not has_winning_move and a ** (b + 1) < n:
        if not can_force_loss(a, b + 1):
            has_winning_move = True

    # If player can force opponent into losing state, player wins
    # Stas goes first
    if has_winning_move:
        # Stas wins, Masha loses
        return "Masha\n\n"
    else:
        # Stas loses, Masha wins
        return "Stas\n\n"

