    S = lines[1].strip()
    T = lines[2].strip()

    result = []
    t_len = len(T)

    def check(start):
        """Check if S[start:start+t_len] can transform to T"""
        mapping = {}
        for i in range(t_len):
            s_char = S[start + i]
            t_char = T[i]

            if s_char == t_char:
                continue

            # They must be different and form a consistent bidirectional pair
            if s_char in mapping:
                # s_char already mapped somewhere else
                if mapping[s_char] != t_char:
                    return False
            elif t_char in mapping:
                # t_char already has a different partner mapping to it
                if mapping[t_char] != s_char:
                    return False
            else:
                # New pair - establish bidirectional mapping
                mapping[s_char] = t_char
                mapping[t_char] = s_char
        return True

    for i in range(n - t_len + 1):
        if check(i):
            result.append(i + 1)

    return f"{len(result)}\n{' '.join(map(str, result))}"

