def find_digit_at_position(k):
    """Find the digit at position k (1-indexed) in the sequence."""

    total_pos = 0
    block_num = 1

    # Find which block contains position k
    while True:
        block_len = get_block_length(block_num)
        if total_pos + block_len >= k:
            # Position k is in this block (or we need to check earlier)
            pos_in_block = k - total_pos
            return get_digit_in_block(pos_in_block, block_num)
        total_pos += block_len
        block_num += 1


def get_block_length(n):
    """Get the total length of block n (concatenation of 1 to n)."""
    if n <= 0:
        return 0

    if n <= 9:
        # Block n = "123...n", length is just n
        return n
    elif n <= 99:
        # 1-9 contribute 9 digits, 10-n contribute 2*(n-9) digits
        return 9 + 2 * (n - 9)
    elif n <= 999:
        # 1-9 contribute 9, 10-99 contribute 9*2, 100-n contribute 3*(n-99)
        return 9 + 18 + 3 * (n - 99)
    elif n <= 9999:
        return 9 + 18 + 27 + 4 * (n - 999)
    else:
        # Handle larger n with formula
        return get_block_length_general(n)


def get_block_length_general(n):
    """Handle very large n by summing contributions per digit group."""
    # For each group of numbers with same digit count
