    # Block length = sum of digit counts for numbers 1 to n

    d = len(str(n))
    total = 0
    seen = [0]  # Track start of each digit group

    for i in range(1, d):
        count = 9 * (10 ** (i-1))
        total += count * i
        seen.append(i)

    # Handle the final partial group
    if d > 1:
        count = n - 9 * (10 ** (d-1)) + 1
        total += count * d

    return total


def get_digit_in_block(pos_in_block, block_num):
