def solution(input_str):
    lines = input_str.strip().split('\n')

    if not lines:
        return ""

    parts = lines[0].split()
    if not parts:
        return ""

    try:
        n, m = map(int, parts[:2])
    except:
        return "0\n"

    if n <= 0 or m <= 0:
        if n <= 0 and m <= 0:
            return "0\n"
        return "0\n" + "." * m + "\n" * (min(n - 1, m - 1))

    # T-shape patterns (5 cells each)
    patterns = [
        [(0,0), (0,1), (0,2), (1,1), (2,1)],  # T pointing up
        [(0,2), (1,0), (1,1), (1,2), (2,2)],  # T pointing down
        [(0,1), (1,1), (2,0), (2,1), (2,2)],  # T pointing left
        [(0,0), (1,1), (1,2), (2,0), (2,1)]   # T pointing right
    ]

    best_count = 0
    best_grid = [[0] * m for _ in range(n)]

    grid = [[0] * m for _ in range(n)]

    def can_place(r, c, pattern):
        """Check if pattern fits at position (r, c)"""
        for dr, dc in pattern:
            nr, nc = r + dr, c + dc
            if nr < 0 or nr >= n or nc < 0 or nc >= m or grid[nr][nc] != 0:
                return False
        return True

    def try_at(r, c, count, char_code):
        nonlocal best_count, best_grid

        # Update best solution
        if count > best_count:
            best_count = count
            best_grid = [row[:] for row in grid]

        # Found optimal
        if best_count == (n * m) // 5:
            return

        # Out of bounds
        if r >= n:
            return

        # Try all 4 orientations at this position
        for i in range(4):
            if can_place(r, c, patterns[i]):
                # Place pattern
                for dr, dc in patterns[i]:
                    grid[r + dr][c + dc] = char_code
                next_char = chr(char_code + 1) if char_code < ord('Z') else 'A'
                try_at(r + 1, 0, count + 1, ord(next_char))
                # Backtrack
                for dr, dc in patterns[i]:
                    grid[r + dr][c + dc] = 0

        # Try next position
        try_at(r + 1, c, count, char_code)

    try_at(0, 0, 0, ord('A'))

    # Format output
    result = []
    result.append(str(best_count))
    for row in best_grid:
        line = []
        for cell in row:
            if cell > 0:
                line.append(chr(cell + 64))
            else:
                line.append('.')
        result.append(''.join(line))
    result.append('')  # trailing newline

    return '\n'.join(result)


