def solution(input_str):
    MOD = 10**9 + 7

    lines = input_str.strip().split('\n')
    q = int(lines[0])
    queries = []
    for i in range(1, q + 1):
        r, n = map(int, lines[i].split())
        queries.append((r, n))

    max_n = 1000001
    MAX_R = 1000005

    # Precompute factorials for combinations
    fact = [1] * MAX_R * 2
    inv = [1] * MAX_R * 2

    for i in range(1, MAX_R * 2):
        fact[i] = (fact[i-1] * i) % MOD

    # Compute modular inverse of factorials
    inv[MAX_R * 2 - 1] = pow(fact[MAX_R * 2 - 1], MOD - 2, MOD)
    for i in range(MAX_R * 2 - 2, -1, -1):
        inv[i] = (inv[i+1] * (i + 1)) % MOD

    def C(n, k):
        if k < 0 or k > n:
            return 0
        return (fact[n] * inv[k] % MOD * inv[n - k] % MOD)

    # Precompute distinct prime factors count for each n up to max_n
    prime_factor_count = [0] * max_n
    is_prime = [True] * max_n
    primes = []
    for i in range(2, max_n):
        if is_prime[i]:
            primes.append(i)
            prime_factor_count[i] = 1
            for j in range(i * i, max_n, i):
                is_prime[j] = False

    for i in range(2, max_n):
        if i in primes:
            continue
        temp = i
        distinct = 0
        for p in primes:
            if p * p > temp:
                break
            if temp % p == 0:
                distinct += 1
                while temp % p == 0:
                    temp //= p
                break
        if temp > 1:
            distinct += 1
        prime_factor_count[i] = distinct

    def count_distinct_primes(n):
        if n == 1:
            return 0
        count = 0
        temp = n
        i = 2
        while i * i <= temp:
            if temp % i == 0:
                count += 1
                while temp % i == 0:
                    temp //= i
            i += 1
        if temp > 1:
            count += 1
        return count

    def get_prime_factorization(n):
        """Returns list of (prime, exponent) pairs"""
        factors = []
        temp = n
        i = 2
        while i * i <= temp:
            if temp % i == 0:
                cnt = 0
                while temp % i == 0:
                    temp //= i
                    cnt += 1
                factors.append((i, cnt))
            i += 1
        if temp > 1:
            factors.append((temp, 1))
        return factors

    results = []

    for r, n in queries:
        if n == 1:
            results.append("1")
            continue

        factors = get_prime_factorization(n)
        res = 1

        for p, k in factors:
            # f_r(p^k) = C(k + r + 1, k)
            res = (res * C(k + r + 1, k)) % MOD

        results.append(str(res))

    return '\n'.join(results)

def solution(input_string):
    n, k, m = map(int, input_string.strip().split())

    MOD = 10**9 + 7

    # Use memoized recursion
    memo = {}

    def count_sequences(current, visited):
        visited = tuple(sorted(visited))
        if len(visited) == k:
            return 1

        state = (current, visited)
        if state in memo:
            return memo[state]

        total = 0
        for next_planet in range(1, current + m + 1):
            if next_planet not in visited:
                total = (total + count_sequences(next_planet, visited + (next_planet,))) % MOD

        memo[state] = total
        return total

    total_ways = 0
    for start in range(1, n + 1):
        total_ways = (total_ways + count_sequences(start, (start,))) % MOD

    return str(total_ways)
